import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"34、【大壯】 乾下震上","description":"周易闡真 - 34、【大壯】 乾下震上","frontmatter":{"title":"34、【大壯】 乾下震上","description":"周易闡真 - 34、【大壯】 乾下震上"},"headers":[],"relativePath":"classics/chanzhen/035.md","filePath":"classics/chanzhen/035.md"}'),s={name:"classics/chanzhen/035.md"};function n(c,a,i,o,l,h){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：大壯，大者壯也。剛以動，故壯。大壯利貞，大者正也。正大，而天地之情可見矣。</p></blockquote><h1 id="_34、【大壯】-乾下震上" tabindex="-1">34、【大壯】 乾下震上 <a class="header-anchor" href="#_34、【大壯】-乾下震上" aria-label="Permalink to “34、【大壯】 乾下震上”">​</a></h1><p>初九：壯於趾，徵兇，有孚。</p><p>九二：貞吉。</p><p>九三：小人用壯，君子用罔，貞厲。羝羊觸藩，羸其角。</p><p>九四：貞吉，悔亡。藩決不羸，壯於大輿之復副本。</p><p>六五：喪羊於易，無悔。</p><p>上六：羝羊觸藩，不能退，不能遂，無攸利。艱則吉。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：雷在天上，大壯。君子以非禮弗履。</p><p>大壯者，大其所壯也。上震雷，下乾天，是雷在天上也。雷為剛烈之物，其氣最壯，升於天上，震驚一切，壯氣更大，此大壯之象也。</p><p>君子有見於此，知雷隨時昇天，能以生物；人順理行事，能以立德。以是非禮弗履焉。禮者，動靜之節、進退之序，為修身應世之規範。凡人師心自用，任性作為，或妄想貪求，恣情縱欲，皆是非禮。非禮之履，不但不能大，而且不能壯，即或有壯，亦是棄真入假之壯，壯非所壯，大不壯矣。若能非禮勿視，非禮勿聽，非禮勿言，非禮勿動，以禮而履，非禮不履，則所履者禮。禮者，理也；理者，天也。履於天理，人慾不生，一步一趨，皆合妙道，與天為徒，與雷同功，居於五行之中，而不為五行所拘，處乎萬物之內，而不為萬物所傷，其壯顧不大哉!</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>羝，音低。羸，音雷。復副本，音福。</p><p>大壯者，陽氣強壯之義。卦德上震動，下乾健，健於內而果於行，健行不息，故為大壯。此進陽壯氣之卦，承上恆卦而來。恆者，久於其道之功。久於其道，則身體力行，心堅志遠，一念不回，深造自得，是非大壯之人不能也。</p><p>蓋大壯之人，自命不凡，俯視一切，放的下，提的起。有大壯之志，即能行大壯之事，作人之所不能作，為人之所不能為，超凡入聖，為天下希有之事，如雷之一動，自地昇天，驚愚駭俗，震動一切矣。</p><p>但大壯之道，尤貴壯之得正，若不得正，則壯之不大，其行不利。彼世間旁門外道之徒，著空執相，認假為真，水火不避，患難不懼，有至死不變者，何嘗不是壯?其如壯之不正，不但壯不能大，而且因壯傷生，何貴於壯?特以大壯之道，惟利於貞耳。</p><p>貞者，正也，理也。以理而壯，則內有主宰而志正，外無妄動而行正。志正則剛強不屈，萬物難移而內壯；行正則果決有斷，諸事能成而外壯。志以固其行，行以全其志，內外兼修，不壯者能壯，已壯者能大。已正而壯，其利寧有限量乎？</p><p>初九，在大壯之始，正當虛己求人，究明性命之理而後用。壯者，乃以剛自居，冒然進步，妄想高登，速欲成功，是壯於其趾矣。壯趾之壯，其進銳者，其退速，遠行必兇，可於理信之。此不謹於始之壯也。</p><p>九二，剛以治內，柔以應外，外不足而內有餘，不壯而壯，壯之有得於中，中而未有不正，正而未有不吉者。此嚴以治己之壯也。</p><p>九三，躁進無忌，不壯於內而壯於外，小人以是而貪圖名利可也。至於修道君子，所當萬有皆空，而亦用壯於外，其壯罔用，不特壯不得正，即得其正，未取於彼，先傷於我，亦是危厲之道。如羝羊觸藩，必羸敗其角。此剛而務外之壯也。</p><p>九四，剛而能柔，陰陽混合，金丹已結，所當正己之後、正人之時，是以貞吉而又悔亡也。貞吉者，正己之吉。悔亡者，正人之悔亡。又近六五，虛心下賢之知音，不但不敗其己之壯，而且能大人之壯，如藩決不羸，壯於大輿之復副本。此正己正人之壯也。</p><p>六五，居於動體，柔而無剛，時在可壯，人不能壯，如喪羊於平易之地矣。然雖人不能壯，幸其柔順虛心，借他人之知識，以開自己之茅塞。虛心即能實腹，不壯者能壯，既壯者能大，可無喪羊之悔矣。此己不壯而借人之壯也。</p><p>上六，愚而自用，妄猜私議，入於旁門，到得年滿月盡，生平所學，俱歸無用，如羝羊觸藩，不能退、不能遂矣。居動之極，禍已釀成，如何能退?在事之終，後悔不及，如何能遂?退之不能，遂之不得，空空一世，有何利乎?然則柔而無能者，與其自己用壯而受害，不若及早虛心求師，困而學之，勉強而行之，從艱難處下一番死功夫，不患不到大壯之地。此本不壯，而歸正即壯也。</p><p>六爻皆有壯道，吉凶不一。求其壯於內，而能正己者，其惟九二；壯於外而能正人者，其惟九四乎？</p><p>然則修道者，當未了道，必先正己；既已了道，又須正人。正己者，修道也；正人者，立德也。修道立德，方是壯之正、壯之大。大壯之利貞，必以道全德備為極功也。</p>',26)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
